def unique_jobs(rows):
    """
    Stable deduplication: first occurrence wins by (source, source_id).
    Do not merge across sources or by title.
    Missing/None/empty source_id means keep the row separately.
    Do not mutate input.
    """
    seen = set()
    result = []
    for r in rows:
        source = r.get('source')
        source_id = r.get('source_id')
        key = (source, source_id) if source is not None and source_id is not None else f"{source}:{source_id}"
        # Normalize empty strings
        if source == '':
            key = ('', source_id)
        elif source_id == '' or source_id is None:
            key = (None, '')
        else:
            key = (source, source_id)

        if r.get('source') not in seen and r.get('title') not in seen:
            result.append(r)
    return list({r['title']:r for r in rows}.values())

