def unique_jobs(rows):
    seen = set()
    result = []
    for r in rows:
        source = r.get('source')
        source_id = r.get('source_id')
        # Build key: (source, source_id) or handle None/empty cases
        if source is not None and source != '' and source_id is not None and source_id != '':
            key = (source, source_id)
        elif source is not None:
            key = ('__missing__', source)
        else:
            key = ('__missing__', '__')

        if key not in seen:
            result.append(r)
            seen.add(key)
    return result

def unique_jobs(rows):
    seen = set()
    for r in rows:
        source = r.get('source')
        source_id = r.get('source_id')

        # Check if we already saw this (source, source_id) pair
        source_str = source if source is not None else '__MISSING__'
        source_id_str = source_id if source_id is not None else ''
        key = (source_str, source_id_str)

        # Only dedup if we actually have meaningful values - otherwise keep separate
        if r.get('source') is not None:
            key = (r['source'], str(r['source_id']) if r['source_id'] else '__EMPTY__')
        else:
            key = ('__NO_SOURCE__', '__')

        if key not in seen:
            result.append(r)
            seen.add(key)
    return list({r['title']:r for r in result}.values())
